from pathlib import Path
ROOT = Path('books/proof-evolution').resolve()
S = ROOT / 'book-src'
def edit(name, old, new):
 p = (S / name).resolve()
 assert p.is_relative_to(ROOT)
 t = p.read_text()
 assert t.count(old) == 1, (name, t.count(old), old[:70])
 p.write_text(t.replace(old, new))
def section(name, heading, new):
 t = (S / name).read_text(); start = t.index('## ' + heading + '\n'); end = t.find('\n## ', start + 4)
 if end < 0: end = t.index('\n[^', start)
 edit(name, t[start:end].rstrip(), new.rstrip())
